import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Helper to format TS file output
const writeTsFile = (filePath: string, varName: string, items: any[]) => {
  const content = `import { IJobQuestionItem } from './banglaQuestions.js';\n\nexport const ${varName}: IJobQuestionItem[] = ${JSON.stringify(
    items,
    null,
    2
  )};\n`;
  fs.writeFileSync(filePath, content, 'utf-8');
  console.log(`[Builder] Wrote ${items.length} questions to ${path.basename(filePath)}`);
};

